/// <summary>
/// MPJ_3863 - kscerri - 05/08/2021
/// constructor
/// </summary>
/// <returns>constructor</returns>
public static METVendAuditReportController construct()
{
    return new METVendAuditReportController();
}

/// <summary>
/// MPJ_3863 - kscerri - 05/08/2021
/// Main method to run report
/// </summary>
/// <param name = "_args">args</param>
public static void main(Args _args)
{
    SrsReportRunController controller  = METVendAuditReportController::construct();
    controller.parmReportName(ssrsReportStr(METVendAuditReport, Report));
    controller.parmArgs(_args);
    controller.parmDialogCaption("@MET:VendAuditReport");
    controller.startOperation();
}
